-- name: CreateMutualFundTrade :one
INSERT INTO mutual_fund_trade (uuid, mutual_fund_id, total_unit, net_asset_value, total_investment_value, trade_type_id, transaction_time, portfolio_id, transaction_date, transaction_fee, mutual_fund_name, description, created_by, updated_by)
VALUES (sqlc.arg('uuid'),
        sqlc.narg('mutual_fund_id'),
        COALESCE(sqlc.narg('total_unit')::numeric, round(sqlc.narg('total_investment_value')::numeric / NULLIF(COALESCE(sqlc.narg('net_asset_value')::numeric, (SELECT mf.net_asset_value FROM mutual_fund mf WHERE mf.id = sqlc.narg('mutual_fund_id'))), 0), 8)),
        COALESCE(sqlc.narg('net_asset_value')::numeric, (SELECT mf.net_asset_value FROM mutual_fund mf WHERE mf.id = sqlc.narg('mutual_fund_id'))),
        COALESCE(sqlc.narg('total_investment_value')::numeric, round(sqlc.narg('total_unit')::numeric * COALESCE(sqlc.narg('net_asset_value')::numeric, (SELECT mf.net_asset_value FROM mutual_fund mf WHERE mf.id = sqlc.narg('mutual_fund_id'))), 4)),
        sqlc.narg('trade_type_id'),
        sqlc.narg('transaction_time'),
        sqlc.narg('portfolio_id'),
        sqlc.narg('transaction_date'),
        sqlc.narg('transaction_fee'),
