    total_investment_value = COALESCE(sqlc.narg('total_investment_value')::numeric, round(sqlc.narg('total_unit')::numeric * COALESCE(sqlc.narg('net_asset_value')::numeric, (SELECT mf.net_asset_value FROM mutual_fund mf WHERE mf.id = sqlc.narg('mutual_fund_id'))), 4)),
